Write {"file_path":"D:\code\ESI.ts\src\schemas\universe.ts","content":"import { z } from 'zod';

const PositionSchema = z.object({
  x: z.number(),
  y: z.number(),
  z: z.number(),
}).passthrough();

export const SolarSystemInfoSchema = z.object({
  system_id: z.number(),
  name: z.string(),
  constellation_id: z.number(),
  security_class: z.string().optional(),
  security_status: z.number(),
  star_id: z.number().optional(),
  stargates: z.array(z.number()).optional(),
  stations: z.array(z.number()).optional(),
  planets: z.array(z.object({
    asteroid_belts: z.array(z.number()).optional(),
    moons: z.array(z.number()).optional(),
    planet_id: z.number(),
  }).passthrough()).optional(),
}).passthrough();

export const ConstellationInfoSchema = z.object({
  constellation_id: z.number(),
  name: z.string(),
  region_id: z.number(),
  systems: z.array(z.number()),
  position: PositionSchema,
}).passthrough();

export const RegionInfoSchema = z.object({
  region_id: z.number(),
  name: z.string(),
  description: z.string().optional(),
  constellations: z.array(z.number()),
}).passthrough();

export const AncestrySchema = z.object({
  id: z.number(),
  name: z.string(),
  bloodline_id: z.number(),
  description: z.string(),
  short_description: z.string().optional(),
  icon_id: z.number().optional(),
}).passthrough();

export const BloodlineSchema = z.object({
  bloodline_id: z.number(),
  name: z.string(),
  description: z.string(),
  race_id: z.number(),
  corporation_id: z.number(),
  ship_type_id: z.number(),
  charisma: z.number(),
  intelligence: z.number(),
  memory: z.number(),
  perception: z.number(),
  willpower: z.number(),
}).passthrough();

export const FactionSchema = z.object({
  faction_id: z.number(),
  name: z.string(),
  description: z.string(),
  size_factor: z.number(),
  station_count: z.number(),
  station_system_count: z.number(),
  is_unique: z.boolean(),
  solar_system_id: z.number().optional(),
  corporation_id: z.number().optional(),
  militia_corporation_id: z.number().optional(),
}).passthrough();

export const RaceSchema = z.object({
  race_id: z.number(),
  name: z.string(),
  description: z.string(),
  alliance_id: z.number(),
}).passthrough();

export const StationInfoSchema = z.object({
  station_id: z.number(),
  name: z.string(),
  owner: z.number().optional(),
  system_id: z.number(),
  type_id: z.number(),
  race_id: z.number().optional(),
  reprocessing_efficiency: z.number(),
  reprocessing_stations_take: z.number(),
  max_dockable_ship_volume: z.number(),
  office_rental_cost: z.number(),
  services: z.array(z.string()),
  position: PositionSchema,
}).passthrough();

export const TypeInfoSchema = z.object({
  type_id: z.number(),
  name: z.string(),
  description: z.string(),
  published: z.boolean(),
  group_id: z.number(),
  market_group_id: z.number().optional(),
  radius: z.number().optional(),
  volume: z.number().optional(),
  capacity: z.number().optional(),
  portion_size: z.number().optional(),
  mass: z.number().optional(),
  icon_id: z.number().optional(),
  graphic_id: z.number().optional(),
  dogma_attributes: z.array(z.object({
    attribute_id: z.number(),
    value: z.number(),
  }).passthrough()).optional(),
  dogma_effects: z.array(z.object({
    effect_id: z.number(),
    is_default: z.boolean(),
  }).passthrough()).optional(),
}).passthrough();

export const AsteroidBeltInfoSchema = z.object({
  name: z.string(),
  position: PositionSchema,
  system_id: z.number(),
}).passthrough();

export const GraphicInfoSchema = z.object({
  graphic_id: z.number(),
  collision_file: z.string().optional(),
  graphic_file: z.string().optional(),
  icon_folder: z.string().optional(),
  sofico_folder: z.string().optional(),
}).passthrough();

export const ItemCategorySchema = z.object({
  category_id: z.number(),
  name: z.string(),
  groups: z.array(z.number()),
  published: z.boolean(),
}).passthrough();

export const ItemGroupSchema = z.object({
  group_id: z.number(),
  name: z.string(),
  category_id: z.number(),
  types: z.array(z.number()),
  published: z.boolean(),
}).passthrough();

export const MoonInfoSchema = z.object({
  moon_id: z.number(),
  name: z.string(),
  system_id: z.number(),
  position: PositionSchema,
}).passthrough();

export const PlanetInfoSchema = z.object({
  planet_id: z.number(),
  name: z.string(),
  system_id: z.number(),
  type_id: z.number(),
  position: PositionSchema,
}).passthrough();

export const StarInfoSchema = z.object({
  star_id: z.number(),
  solar_system_id: z.number(),
  name: z.string(),
  type_id: z.number(),
  age: z.number(),
  luminosity: z.number(),
  radius: z.number(),
  spectral_class: z.string(),
  temperature: z.number(),
}).passthrough();

export const StargateInfoSchema = z.object({
  stargate_id: z.number(),
  name: z.string(),
  system_id: z.number(),
  type_id: z.number(),
  position: PositionSchema,
  destination: z.object({
    system_id: z.number(),
    stargate_id: z.number(),
  }).passthrough(),
}).passthrough();

export const StructureInfoSchema = z.object({
  structure_id: z.number(),
  name: z.string(),
  owner_id: z.number(),
  solar_system_id: z.number(),
  type_id: z.number().optional(),
  position: PositionSchema.optional(),
}).passthrough();

export const SystemJumpSchema = z.object({
  system_id: z.number(),
  ship_jumps: z.number(),
}).passthrough();

export const SystemKillSchema = z.object({
  system_id: z.number(),
  npc_kills: z.number(),
  pod_kills: z.number(),
  ship_kills: z.number(),
}).passthrough();

const IdNameSchema = z.object({
  id: z.number(),
  name: z.string(),
}).passthrough();

export const BulkIdResultSchema = z.object({
  agents: z.array(IdNameSchema).optional(),
  alliances: z.array(IdNameSchema).optional(),
  characters: z.array(IdNameSchema).optional(),
  constellations: z.array(IdNameSchema).optional(),
  corporations: z.array(IdNameSchema).optional(),
  factions: z.array(IdNameSchema).optional(),
  inventory_types: z.array(IdNameSchema).optional(),
  regions: z.array(IdNameSchema).optional(),
  systems: z.array(IdNameSchema).optional(),
  stations: z.array(IdNameSchema).optional(),
}).passthrough();

export const NameAndCategorySchema = z.object({
  id: z.number(),
  name: z.string(),
  category: z.enum([
    'alliance',
    'character',
    'constellation',
    'corporation',
    'inventory_type',
    'region',
    'solar_system',
    'station',
    'faction',
  ]),
}).passthrough();

export const SchematicInfoSchema = z.object({
  schematic_name: z.string(),
  cycle_time: z.number(),
}).passthrough();

export const SearchResultSchema = z.object({
  agent: z.array(z.number()).optional(),
  alliance: z.array(z.number()).optional(),
  character: z.array(z.number()).optional(),
  constellation: z.array(z.number()).optional(),
  corporation: z.array(z.number()).optional(),
  faction: z.array(z.number()).optional(),
  inventory_type: z.array(z.number()).optional(),
  region: z.array(z.number()).optional(),
  solar_system: z.array(z.number()).optional(),
  station: z.array(z.number()).optional(),
  structure: z.array(z.number()).optional(),
}).passthrough();
"}

